 "content": "def transform(grid):
    """Collapse consecutive identical rows and columns."""
    rows = [list(row) for row in grid]
    compact_rows = []
    for row in rows:
        if not compact_rows or row != compact_rows[-1]:
            compact_rows.append(row)

    compact = []
    for r, row in enumerate(compact_rows):
        out_row = []
        for c, value in enumerate(row):
            if r == 0 or any(compact_rows[rr][c] != compact_rows[rr][c - 1] for rr in range(len(compact_rows))):
                out_row.append(value)
        compact.append(out_row)
    return compact
